            }
},
.hypot => |*args| {
{
                _ = try dest.writeStr("hypot(");
                var first = true;
                _ = &first;
                for (args.items) |*arg| {
                    _ = &arg;
                    if (first) {
                        first = false;
                    } else {
                        _ = try dest.delim(44, false);
                    }
                    _ = try arg.toCss(dest);
                }
                _ = try dest.writeChar(41);
