            for (m.items) |*arg| {
                _ = &arg;
                if ((!arg.isCompatible(browsers))) {
                    break :brk false;
                }
            }
            break :brk true;
}),
.max => |*m| (F.isCompatible(F.max_function, browsers) and brk: {
            for (m.items) |*arg| {
                _ = &arg;
                if ((!arg.isCompatible(browsers))) {
