pub fn arr2(allocator: std.mem.Allocator, a: anytype, b: anytype) ArrayList(@TypeOf(a)) {
        const T = @TypeOf(a);
        if ((T != @TypeOf(b))) {
            _ = @compileError("arr2: types must match");
        }
        var arr: ArrayList(T) = .{};
        _ = &arr;
        const items: [2]T = .{ a, b };
        _ = bun.handleOom(arr.appendSlice(allocator, (&items)));
        return arr;
}

pub fn round(_: void, value: f32, to: f32, strategy: RoundingStrategy) f32 {
        const v = (value / to);
        return (switch (strategy) {
.down => (@floor(v) * to),
.up => (@ceil(v) * to),
.nearest => (@round(v) * to),
.@"to-zero" => (@trunc(v) * to),
});
}

pub fn hypot(_: void, a: f32, b: f32) f32 {
        return std.math.hypot(a, b);
}

pub fn powi2(v: f32) f32 {
        return bun.powf(v, 2);
}

pub fn sqrtf32(v: f32) f32 {
        return std.math.sqrt(v);
}

pub fn absf(a: f32) f32 {
        return @abs(a);
}
